<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {RefreshCw} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createCalibration,rederiveCalibration} from '../api/calibrations';import LibrarySelector from '../components/LibrarySelector.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';import {parseBlankReadings,blankText} from '../utils/blank';import {number,scientific} from '../utils/format';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),selected=ref(Number(route.query.library)||0),name=ref(''),source=ref(''),text=ref(''),rederiveName=ref(''),rederiveId=ref(0);const library=computed(()=>s.libraries.find(l=>l.id===selected.value)||s.libraries[0]);const preview=computed(()=>parseBlankReadings(text.value,library.value?.wavelengths.length||0));const libraryCalibrations=computed(()=>s.calibrations.filter(c=>c.library_id===library.value?.id));watch(()=>library.value?.id,async id=>{if(id){await s.loadLibrary(id);await s.loadCalibrations(id);rederiveId.value=0}},{immediate:true});function submit(){a.execute(async()=>{const readings=text.value.split(/\r?\n/).map(l=>l.trim()).filter(Boolean).map(l=>l.split(/[,，\s]+/).filter(Boolean).map(Number));await createCalibration({name:name.value,library_id:library.value.id,source:source.value,readings});name.value='';text.value='';source.value='';await s.loadCalibrations(library.value.id)})}function rederive(id:number){a.execute(async()=>{await rederiveCalibration(id,{name:rederiveName.value});rederiveId.value=0;rederiveName.value='';await s.loadCalibrations(library.value.id)})}function loadReadings(id:number){const c=libraryCalibrations.value.find(x=>x.id===id);if(c){rederiveId.value=id;text.value=blankText(c.readings);rederiveName.value=c.name+' · 按当前规则重算'}}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">BLANK NOISE CALIBRATION / 05</p><h1>空白测谱校准<span>相邻波段相关，不能当成独立等方差扰动。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><LibrarySelector :libraries="s.libraries" :model-value="library?.id||0" @update:model-value="selected=$event"/><div v-if="library" class="library-diagnostic"><span>{{library.code}} / {{library.wavelengths.length}} 波段 · 空白重复一次一行</span><p>扣除各波段均值后估计联合协方差；缺波段、无效读数或退化校准都会明确报错，不会静默退回独立噪声。</p></div><div class="editor-grid"><form @submit.prevent="submit"><label>校准名称<input aria-label="校准名称" v-model="name" minlength="2" maxlength="120" required placeholder="例如：校准库 · 空白测谱批次-02" :disabled="auth.user?.role==='viewer'"/></label><label>来源说明<input aria-label="校准来源" v-model="source" maxlength="160" placeholder="例如：同一空池、同一仪器设置下的重复测谱"/></label><div class="form-heading"><span>01</span><h2>空白重复读数</h2></div><textarea aria-label="空白重复读数" v-model="text" placeholder="每行一次重复，按波段以逗号分隔；例如：&#10;0.0012, -0.0004, 0.0008, ..." :disabled="auth.user?.role==='viewer'"/><div class="blank-preview"><div><span>行数</span><b>{{preview.rows}}</b></div><div><span>完整读数</span><b>{{preview.complete}}</b></div><div><span>协方差自由度</span><b>{{preview.degreesOfFreedom}}</b></div><strong :class="preview.valid?'supported':'warning'">{{preview.valid?'可估计联合协方差':'不足以估计联合协方差'}}</strong></div><ul v-if="preview.issues.length" class="blank-issues"><li v-for="(issue,i) in preview.issues.slice(0,6)" :key="i">{{issue}}</li><li v-if="preview.issues.length>6">另有{{preview.issues.length-6}}处</li></ul><p class="caption">至少需要“波段数+1”次完整重复；每行必须覆盖全部波段，缺波段或非有限值整批不用于校准。估计结果同时记录有效测量数与自由度。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="a.busy.value||!library||!preview.valid||name.length<2">建立空白校准</button><p v-else class="role-note">阅读者可查阅校准来源，建立或重算需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">CALIBRATION NOTE / 01</span><h2>相关噪声，<br/>联合估计。</h2><ol><li><b>扣除波段均值</b><p>空白重复先去均值，再估计无偏样本协方差；均值本身不做配比。</p></li><li><b>整批有效或整批拒绝</b><p>缺波段、无效读数、秩亏或条件数超过1e6都明确拒绝，不悄悄换成独立σ。</p></li><li><b>研究冻结来源</b><p>新研究冻结校准与读数指纹；规则更新后旧研究保留原来源，新研究重算校准。</p></li></ol></aside></div><div class="section-heading"><h2>本库校准档案</h2><span>有效测量数即参与协方差估计的完整空白重复</span></div><DataTable :head="['校准','规则','有效测量数','协方差自由度','噪声RMS','条件数','来源','操作']"><tr v-for="c in libraryCalibrations" :key="c.id"><td class="mono">#{{c.id}} / {{c.name}}<small v-if="c.derived_from_id"> 由 #{{c.derived_from_id}} 重算</small></td><td><span :class="c.rule_current?'supported':'warning'">{{c.rule_version}}{{c.rule_current?'':' / 旧规则'}}</span></td><td>{{c.effective_measurements}}<small> / {{c.readings_count}}行</small></td><td>{{c.degrees_of_freedom}}</td><td>{{number(c.noise_rms,5)}}</td><td>{{scientific(c.condition_number)}}</td><td class="note-cell">{{c.source}}<small class="fingerprint">{{c.calibration_hash}}</small></td><td><button v-if="!c.rule_current&&auth.user?.role!=='viewer'" class="text-link" @click="loadReadings(c.id)">按当前规则重算</button><span v-else-if="c.rule_current" class="caption">当前规则</span></td></tr></DataTable><div v-if="rederiveId" class="annotation"><label>重算名称<input aria-label="重算名称" v-model="rederiveName" minlength="2" required/></label><button class="primary" :disabled="a.busy.value" @click="rederive(rederiveId)"><RefreshCw :size="14"/>重算 #{{rederiveId}}</button><button class="outline" type="button" @click="rederiveId=0">取消</button></div><p v-if="!libraryCalibrations.length" class="empty">该库尚无空白校准；未选择校准时新研究仍可使用旧版独立噪声。</p></div></template>
